class ProtocolHandlerRegistry:
    _handlers = {
        (3, 0): 'Handler30',
        (3, 1): 'Handler31',
        (3, 2): 'Handler32',
        (3, 3): 'Handler33',
        (3, 4): 'Handler34',
        (3, 5): 'Handler35',
    }

    @classmethod
    def protocol_handlers(cls, protocol_version=None):
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be provided as a tuple")

        if protocol_version is None:
            return cls._handlers

        return {protocol_version: cls._handlers.get(protocol_version, None)} if protocol_version in cls._handlers else {}

