from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, maxsize=128):
        self.maxsize = maxsize
        self.cache = {}
        self.freq = defaultdict(OrderedDict)
        self.min_freq = 0

    def get(self, key):
        if key not in self.cache:
            return None
        freq = self.cache[key][1]
        value = self.cache[key][0]
        self.freq[freq].pop(key)
        if not self.freq[freq]:
            del self.freq[freq]
            if freq == self.min_freq:
                self.min_freq += 1
        self.freq[freq + 1][key] = value
        self.cache[key] = (value, freq + 1)
        return value

    def put(self, key, value):
        if self.maxsize <= 0:
            return
        if key in self.cache:
            self.cache[key] = (value, self.cache[key][1])
            self.get(key)
            return
        if len(self.cache) >= self.maxsize:
            pop_key, _ = self.freq[self.min_freq].popitem(last=False)
            del self.cache[pop_key]
            if not self.freq[self.min_freq]:
                del self.freq[self.min_freq]
        self.cache[key] = (value, 1)
        self.freq[1][key] = value
        self.min_freq = 1

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = LFUCache(maxsize=maxsize)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if not typed else (args, kwargs)
            value = cache.get(key)
            if value is None:
                value = func(*args, **kwargs)
                cache.put(key, value)
            return value
        return wrapper
    return decorator

