import copy

def difference(d1, d2, level=-1):
    def _difference(sub_d1, sub_d2, current_level):
        if current_level == 0:
            return {}
        result = {}
        for key in sub_d1:
            if key not in sub_d2:
                result[key] = sub_d1[key]
            elif isinstance(sub_d1[key], dict) and isinstance(sub_d2[key], dict):
                diff = _difference(sub_d1[key], sub_d2[key], current_level - 1)
                if diff:
                    result[key] = diff
            elif sub_d1[key] != sub_d2[key]:
                result[key] = sub_d1[key]
        return result

    return _difference(d1, d2, level if level != -1 else float('inf'))

import numpy as np

class Histogram:
    def __init__(self, shape):
        self.histogram = np.zeros(shape)

    def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        if all(0 <= c < s for c, s in zip(coord, self.histogram.shape)):
            self.histogram[coord] += weight

import re

class ValidationError(Exception):
    def __init__(self, messages):
        self.messages = messages
        super().__init__(self._generate_error_message())

    def _generate_error_message(self):
        return "\n".join(str(msg) for msg in self.messages)

def _validate_labels(labels):
    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    errors = []

    for key, value in labels.items():
        key_str = str(key)
        value_str = str(value)

        if not isinstance(key, (str, int, float, bool)):
            errors.append({key_str: 'expected string or bytes-like object'})
        elif not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

        if not isinstance(value, (str, int, float, bool)):
            errors.append({value_str: 'expected string or bytes-like object'})
        elif not value_regex.match(value_str):
            errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})


    if errors:
        raise ValidationError(errors)

# Example usage
if __name__ == "__main__":
    labels = {
        "key1": "valid",
        "key2": ["invalid"],
        "$$": "invalid",
        True: True,
    }
    try:
        _validate_labels(labels)
    except ValidationError as err:
        print(err.messages)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    identifying_fields = {'apiVersion', 'kind', 'metadata', 'name'}
    observer_schema = {}

    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            observer_schema[key] = value
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for obs_schema, resp_item in zip(observer_schema, response):
        if isinstance(obs_schema, dict) and isinstance(resp_item, dict):
            for key, value in obs_schema.items():
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = value
                elif isinstance(value, list) and isinstance(last_applied_manifest[key], list):
                    update_last_applied_manifest_list_from_resp(last_applied_manifest[key], value, resp_item.get(key, []))
                elif isinstance(value, dict) and isinstance(last_applied_manifest[key], dict):
                    update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, resp_item.get(key, {}))
        elif isinstance(obs_schema, list) and isinstance(resp_item, list):
            for i, item_schema in enumerate(obs_schema):
                if i >= len(last_applied_manifest):
                    last_applied_manifest.append(item_schema)
                update_last_applied_manifest_list_from_resp(last_applied_manifest[i], item_schema, resp_item[i] if i < len(resp_item) else {})

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, value in observer_schema.items():
        if key not in last_applied_manifest:
            last_applied_manifest[key] = value
        elif isinstance(value, list) and isinstance(last_applied_manifest[key], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[key], value, response.get(key, []))
        elif isinstance(value, dict) and isinstance(last_applied_manifest[key], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, response.get(key, {}))

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for field, schema in observer_schema.items():
        if field in response:
            if isinstance(schema, dict) and isinstance(response[field], dict):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, response[field]
                )
            else:
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = response[field]
        else:
            raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")

