from typing import AnyStr, Union, Dict, Sequence, Tuple, Any
import re

class SQLParams:
    IN_STYLE_NAMED = 'named'
    IN_STYLE_ORDINAL = 'ordinal'

    def __init__(self, in_style: str):
        self.in_style = in_style

    def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        if self.in_style == self.IN_STYLE_NAMED:
            out_params = {f":{key}": value for key, value in params.items()}
            for key in params:
                sql = sql.replace(f":{key}", f":{key}")
            return sql, out_params
        elif self.in_style == self.IN_STYLE_ORDINAL:
            out_params = [value for value in params]
            param_count = 0
            def replace_param(match):
                nonlocal param_count
                param_count += 1
                return f":{param_count}"
            sql = re.sub(r'%s', replace_param, sql)
            return sql, out_params
        else:
            raise ValueError("Unsupported in-style parameter type")

from typing import AnyStr, Union, Iterable, Dict, Sequence, List, Tuple
import re

class SQLParams:
    in_style = 'named'  # or 'ordinal'

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if SQLParams.in_style == 'named':
        pattern = re.compile(r':([a-zA-Z_][a-zA-Z0-9_]*)')
        out_style_params = []
        for params in many_params:
            new_sql = sql
            new_params = {}
            for key, value in params.items():
                new_sql = new_sql.replace(f':{key}', f'%({key})s')
                new_params[key] = value
            out_style_params.append(new_params)
        return new_sql, out_style_params
    elif SQLParams.in_style == 'ordinal':
        pattern = re.compile(r'\?')
        out_style_params = []
        for params in many_params:
            new_sql = sql
            new_params = []
            for value in params:
                new_sql = pattern.sub('%s', new_sql, count=1)
                new_params.append(value)
            out_style_params.append(new_params)
        return new_sql, out_style_params
    else:
        raise ValueError("Unsupported in_style. Use 'named' or 'ordinal'.")

import os
import json
import hashlib

class OCFLValidator:
    def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        if not os.path.exists(path):
            return False

        # Check for required files
        required_files = ['0=ocfl_object_1.0', 'inventory.json']
        for file in required_files:
            if not os.path.isfile(os.path.join(path, file)):
                return False

        # Validate inventory.json
        inventory_path = os.path.join(path, 'inventory.json')
        try:
            with open(inventory_path, 'r', encoding='utf-8') as f:
                inventory = json.load(f)
        except (json.JSONDecodeError, IOError):
            return False

        # Check for required fields in inventory
        required_fields = ['id', 'type', 'digestAlgorithm', 'manifest']
        for field in required_fields:
            if field not in inventory:
                return False

        # Validate manifest entries
        for digest, files in inventory['manifest'].items():
            for file_path in files:
                file_full_path = os.path.join(path, file_path)
                if not os.path.isfile(file_full_path):
                    return False
                if not self._validate_file_digest(file_full_path, digest, inventory['digestAlgorithm']):
                    return False

        return True

    def _validate_file_digest(self, file_path, expected_digest, algorithm):
        hash_func = hashlib.new(algorithm)
        try:
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_func.update(chunk)
        except IOError:
            return False
        return hash_func.hexdigest() == expected_digest

