import logging
import os
import json

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if resolve_env:
                    config = resolve_environment_variables(config)
                if overrides:
                    config.update(overrides)
                config_dict[filename] = config
        except Exception as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True)
            log_records.append(record)

    return config_dict, log_records

def resolve_environment_variables(config):
    if isinstance(config, dict):
        return {k: resolve_environment_variables(v) for k, v in config.items()}
    elif isinstance(config, list):
        return [resolve_environment_variables(i) for i in config]
    elif isinstance(config, str):
        return os.path.expandvars(config)
    else:
        return config

