def hist_to_graph(hist: Histogram, make_value: Callable[[float], Union[float, Tuple[float, ...]]] = None,
                  get_coordinate: str = "left", field_names: Tuple[str, ...] = ("x", "y"), scale=None) -> Graph:
    if make_value is None:
        make_value = lambda bin_content: bin_content

    points = []
    for bin_left, bin_content in hist.bins:
        if get_coordinate == "left":
            x = bin_left
        elif get_coordinate == "right":
            x = bin_left + (hist.bins[hist.bins.index((bin_left, bin_content)) + 1][0] - bin_left) if hist.bins.index((bin_left, bin_content)) < len(hist.bins) - 1 else bin_left + 1
        elif get_coordinate == "middle":
            x = bin_left + (hist.bins[hist.bins.index((bin_left, bin_content)) + 1][0] - bin_left) / 2 if hist.bins.index((bin_left, bin_content)) < len(hist.bins) - 1 else bin_left + 0.5
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        y = make_value(bin_content)
        if isinstance(y, tuple):
            point = (x,) + y
        else:
            point = (x, y)
        points.append(point)

    if scale is True:
        graph_scale = hist.scale
    else:
        graph_scale = scale

    return Graph(points, field_names, graph_scale)

from zope.interface import Interface, implementer, providedBy, Invalid
from inspect import signature, Parameter

class IExample(Interface):
    def method1(arg1, arg2):
        """Method 1 description"""

    def method2(arg1):
        """Method 2 description"""

    attr1 = Attribute("Attribute 1 description")
    attr2 = Attribute("Attribute 2 description")

@implementer(IExample)
class Candidate:
    def method1(self, arg1, arg2):
        pass

    def method2(self, arg1):
        pass

    attr1 = "value1"
    attr2 = "value2"

def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}")

    for name, method in iface.namesAndDescriptions(all=True):
        if isinstance(method, Interface.Method):
            if not hasattr(candidate, name):
                errors.append(f"Missing method: {name}")
            else:
                candidate_method = getattr(candidate, name)
                if not callable(candidate_method):
                    errors.append(f"Not callable: {name}")
                else:
                    try:
                        sig = signature(candidate_method)
                        iface_sig = signature(method)
                        if not sig.parameters:
                            errors.append(f"Method {name} has no parameters")
                        for param_name, param in iface_sig.parameters.items():
                            if param_name not in sig.parameters:
                                errors.append(f"Missing parameter {param_name} in method {name}")
                            else:
                                candidate_param = sig.parameters[param_name]
                                if candidate_param.kind != param.kind:
                                    errors.append(f"Parameter {param_name} in method {name} has incorrect kind")
                                if candidate_param.annotation != param.annotation:
                                    errors.append(f"Parameter {param_name} in method {name} has incorrect annotation")
                    except ValueError as e:
                        errors.append(f"Error checking signature for method {name}: {e}")

        elif isinstance(method, Interface.Attribute):
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

