class CommandProcessor:
    def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required_args = []
        for option in options_spec:
            if 'required_when' in option:
                condition = option['required_when']
                if condition == command_name or (isinstance(condition, list) and command_name in condition):
                    arg_name = option.get('name')
                    if arg_name and arg_name not in args:
                        required_args.append(arg_name)
        return required_args

# Example usage
if __name__ == "__main__":
    processor = CommandProcessor()
    command_name = "example_command"
    options_spec = [
        {'name': 'arg1', 'required_when': 'example_command'},
        {'name': 'arg2', 'required_when': ['example_command', 'another_command']},
        {'name': 'arg3', 'required_when': 'different_command'}
    ]
    args = {'arg1': 'value1'}
    print(processor._get_conditionally_required_args(command_name, options_spec, args))

